// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 sequenceNumber,
        bytes32 batcherHash,
        uint256 l1FeeOverhead,
        uint256 l1FeeScalar
    ) public {
        vm.assume(l1FeeOverhead != 0);
        // depositorAccount defaults to address(0); call from it so the require passes
        vm.prank(address(0));
        c.setL1BlockValues(
            number,
            timestamp,
            basefee,
            hash,
            sequenceNumber,
            batcherHash,
            l1FeeOverhead,
            l1FeeScalar
        );
        // General rule: a completed setL1BlockValues never changes c's stored l1FeeOverhead
        assertTrue(c.l1FeeOverhead() == 0);
    }
}
